import React, { useEffect, useState } from 'react';
import { FaPhone, FaMapMarkerAlt } from 'react-icons/fa';
import './footer.css';

const Footer = () => {
  const [isVisible, setIsVisible] = useState(false);
  const [lastScrollPos, setLastScrollPos] = useState(0);

  useEffect(() => {
    const handleScroll = () => {
      const currentScrollPos = window.scrollY;
      const scrollDirection = currentScrollPos > lastScrollPos ? 'down' : 'up';
      setLastScrollPos(currentScrollPos);

      const pageBottom = window.innerHeight + currentScrollPos;
      const threshold = 150; // Show when 150px from bottom

      if (scrollDirection === 'down' && 
          (document.documentElement.scrollHeight - pageBottom < threshold)) {
        setIsVisible(true);
      } else if (scrollDirection === 'up') {
        setIsVisible(false);
      }
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, [lastScrollPos]);

  return (
    <footer className={`footer ${isVisible ? 'visible' : ''}`}>
      <div className="footer-content">
        <div className="footer-contact">
          <span><FaPhone /> +91 9876543210</span>
          <span><FaMapMarkerAlt /> 123 Food Street, Mumbai</span>
        </div>
        <div className="footer-copyright">
          © {new Date().getFullYear()} Hotel Shyam
        </div>
      </div>
    </footer>
  );
};

export default Footer;
